/* REHABOOM 4.0 — practice workflow. No example patients or invented results. */
(()=>{
 'use strict';
 const C=CareModel,K=CareCrypto,ids=new Set(EX.map(e=>e.id)),root=$('view-care');
 const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d;}catch{return d;}};
 let state=read('rb-care-v1',C.empty());if(!C.validateState(state,ids))state=C.empty();if(!state.portals)state.portals={};
 let selected=state.clients[0]?.id||'',page='dashboard',draft=null,runner=null,portal=null,portalData=null;
 let chosenExercise='',chartMetric='load',chartMeasure='',restUntil=0,restInterval=null,portalBusy=false;
 const DAYS=['Zo','Ma','Di','Wo','Do','Vr','Za'];
 const ex=id=>EX.find(e=>e.id===id),clientRecord=()=>portal?portalData?.client:state.clients.find(c=>c.id===selected);
 const fmt=d=>d?new Intl.DateTimeFormat('nl-NL',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00')):'Nog niet gepland';
 const notice=document.createElement('div');notice.className='care-toast';notice.setAttribute('role','status');notice.hidden=true;document.body.append(notice);let noticeTimer;
 function tell(s){notice.textContent=s;notice.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.hidden=true,5500);}
 function persist(){try{localStorage.setItem('rb-care-v1',JSON.stringify(state));return true;}catch{tell('Opslag is vol of niet beschikbaar. Exporteer je gegevens voordat je verdergaat.');return false;}}
 function programs(){return portal?portalData?.programs||[]:state.programs.filter(p=>p.clientId===selected&&!p.archived);}
 function sessions(){return (portal?portalData?.sessions||[]:state.sessions).filter(s=>s.clientId===clientRecord()?.id);}
 function measurements(){return (portal?portalData?.measurements||[]:state.measurements).filter(m=>m.clientId===clientRecord()?.id);}
 function newProgram(){return {id:C.uid(),clientId:selected,title:'Nieuw programma',days:[1,3,5],items:[],note:'',privateNote:'',updatedAt:Date.now()};}
 function newItem(id){return {id:C.uid(),exId:id,sets:3,reps:/plank|pallof/.test(id)?30:10,unit:/plank/.test(id)?'seconds':'reps',rest:90,tempo:'',load:0,note:''};}
 function action(label,attr,primary=false){return `<button class="care-btn${primary?' primary':''}" ${attr}>${label}</button>`;}
 function empty(title,body,buttons=''){return `<div class="care-empty"><span class="care-empty-icon" aria-hidden="true">＋</span><h3>${title}</h3><p>${body}</p><div class="care-actions">${buttons}</div></div>`;}
 const modal=document.createElement('dialog');modal.className='care-dialog';modal.setAttribute('aria-labelledby','care-dialog-title');document.body.append(modal);
 function showDialog(title,body){modal.innerHTML=`<button class="care-dialog-close" data-care-close aria-label="Sluiten">×</button><h2 id="care-dialog-title">${title}</h2>${body}<p class="form-error" role="alert" id="care-error"></p>`;if(!modal.open)modal.showModal();}
 function formError(text){modal.querySelector('#care-error').textContent=text;}
 const publicAppUrl='https://rehaboom.vercel.app/';
 const appQrImage='icons/rehaboom-qr.png';
 function shareAppDialog(){
  showDialog('Deel Rehaboom met testers',`<p>Laat iemand deze QR-code scannen met de camera van een telefoon. De code opent de openbare Rehaboom-app.</p>
   <img class="app-share-qr" src="${appQrImage}" width="370" height="370" alt="QR-code voor ${publicAppUrl}">
   <label for="app-share-url">Openbare testlink<input id="app-share-url" type="url" readonly value="${publicAppUrl}"></label>
   <div class="care-actions">
    ${action('Kopieer link','type="button" data-care="copy-app-link"',true)}
    <a class="care-btn app-share-download" href="${appQrImage}" download="Rehaboom-QR-code.png">Download QR-code</a>
   </div>
   <p class="app-share-status" id="app-share-status" role="status"></p>`);
 }
 async function copyAppLink(){
  const field=$('app-share-url'),status=$('app-share-status');
  try{
   await navigator.clipboard.writeText(publicAppUrl);
   status.textContent='Testlink gekopieerd.';
  }catch{
   field.focus();
   field.select();
   status.textContent='Testlink geselecteerd. Je kunt hem nu kopiëren.';
  }
 }
 function header(){const c=clientRecord();return `<div class="care-heading"><div><span class="care-eyebrow">REHABOOM · ${portal?'CLIËNTPORTAAL':'PRAKTIJK'}</span><h2>${portal?'Jouw begeleiding':'Begeleiding'}</h2><p>${portal?'Je programma, training en voortgang op één plek.':'Van jouw plan naar uitvoering en een gerichte evaluatie.'}</p></div><div class="care-actions">${portal?action('Portaal verlaten','data-care="leave-portal"'):action('Gegevens & portaal','data-care="data"')+action('Cliënt toevoegen','data-care="new-client"',true)}</div></div>${portal?`<div class="portal-banner"><span class="care-dot"></span><strong>${esc(c?.name||'Cliënt')}</strong><span id="portal-status">Eigen programma en resultaten</span>${action('Bijwerken','data-care="refresh-portal"')}</div>`:state.clients.length?`<div class="client-bar"><label for="care-client">Cliënt</label><select id="care-client" aria-label="Geselecteerde cliënt">${state.clients.map(c=>`<option value="${c.id}"${c.id===selected?' selected':''}>${esc(c.name)}</option>`).join('')}</select>${c?action('Profiel bewerken','data-care="edit-client"'):''}<span class="care-local">Bewaard op dit toestel</span></div>`:''}`;}
 function render(){
  if(!root)return;
  root.innerHTML=header();const c=clientRecord();
  if(!c){root.insertAdjacentHTML('beforeend',empty('Een persoonlijk begin','Voeg je eerste cliënt toe. Stel daarna een programma samen en volg trainingen en evaluaties.',action('Eerste cliënt toevoegen','data-care="new-client"',true)+action('Cliëntportaal openen','data-care="join-portal"')));return;}
  root.insertAdjacentHTML('beforeend',`<div class="care-tabs" role="group" aria-label="Begeleidingsonderdeel">${[['dashboard','Overzicht'],['programs',portal?'Mijn programma':'Programma’s'],['progress','Voortgang'],...(!portal?[['evaluation','Evaluatie']]:[])].map(([id,label])=>`<button data-care-page="${id}" aria-pressed="${page===id}">${label}</button>`).join('')}</div><div id="care-content">${runner?renderRunner():page==='programs'?renderPrograms():page==='progress'?renderProgress():page==='evaluation'?renderEvaluation():renderDashboard()}</div>`);
  if(runner)restoreRunnerDraft();
  else if(read(runnerKey(),null))$('care-content').insertAdjacentHTML('afterbegin',`<div class="resume-banner"><p>Er staat een onafgeronde training op dit toestel.</p>${action('Training hervatten','data-care="resume-training"',true)}</div>`);
 }
 window.rbRenderCare=render;
 function renderDashboard(){
  const c=clientRecord(),ps=programs(),ss=sessions(),stats=C.weeklyStats(ps,ss),next=C.nextTraining(ps),recent=[...ss].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);
  const due=c.evaluation&&c.evaluation<=C.localDate();
  return `<div class="care-kpis"><div><span>Trainingen deze week</span><strong>${stats.done}<small>${stats.planned?' / '+stats.planned:' geregistreerd'}</small></strong><p>${stats.planned?'Volgens het huidige weekschema':'Stel trainingsdagen in je programma in'}</p></div><div><span>Volgende training</span><strong class="kpi-date">${next?fmt(next.date):'Nog geen schema'}</strong><p>${next?esc(next.programs.map(p=>p.title).join(' · ')):'Maak een programma om te beginnen'}</p></div><div><span>Evaluatiemoment</span><strong class="kpi-date${due?' due':''}">${fmt(c.evaluation)}</strong><p>${due?'Het geplande evaluatiemoment is bereikt':'Samen bekijken wat werkt en wat bijsturing vraagt'}</p></div></div><div class="care-grid"><section class="care-panel goal-panel"><span class="care-eyebrow">PERSOONLIJK DOEL</span><h3>${esc(c.name)}</h3><p>${esc(c.goal||'Leg samen een concreet doel vast in het profiel.')}</p><div class="care-actions">${ps.length?action('Training starten',`data-start-program="${(next?.programs[0]||ps[0]).id}"`,true):!portal?action('Programma maken','data-care="new-program"',true):''}${!portal?action('Cliëntportaal beheren','data-care="portal"'):''}</div></section><section class="care-panel"><div class="panel-heading"><h3>Recente trainingen</h3>${action('Alle resultaten','data-care-page="progress"')}</div>${recent.length?recent.map(s=>`<div class="history-row"><div><b>${esc(s.title||'Training')}</b><span>${fmt(s.date)} · ${s.items.reduce((n,i)=>n+i.sets.length,0)} sets</span></div><span class="effort-pill">RPE ${s.rpe}</span></div>`).join(''):'<p class="care-muted">Je ziet hier de trainingen zodra er een training is afgerond.</p>'}</section></div>${ps.length?`<section class="care-panel"><h3>${portal?'Jouw programma’s':'Toegewezen programma’s'}</h3><div class="program-grid">${ps.map(programCard).join('')}</div></section>`:''}`;
 }
 function programCard(p){return `<article class="program-card"><span class="care-eyebrow">${p.days.map(d=>DAYS[d]).join(' · ')||'Flexibele trainingsdagen'}</span><h4>${esc(p.title)}</h4><p>${p.items.length} oefeningen · ${p.items.reduce((n,i)=>n+i.sets,0)} geplande sets</p><div class="care-actions">${action('Start training',`data-start-program="${p.id}"`,true)}${action(portal?'Bekijken':'Bewerken',`data-edit-program="${p.id}"`)}</div></article>`;}
 function renderPrograms(){
  if(draft)return renderEditor();
  const ps=programs();
  if(portal&&draft===null)return ps.length?`<div class="program-grid">${ps.map(programCard).join('')}</div>`:empty('Nog geen programma','Je coach kan hier een programma voor je publiceren.');
  return `<div class="panel-heading"><div><h3>Programma’s voor ${esc(clientRecord().name)}</h3><p class="care-muted">Pas dosering en instructies aan de cliënt aan.</p></div><div class="care-actions">${action('Uit sjabloon','data-care="templates"')}${action('Nieuw programma','data-care="new-program"',true)}</div></div>${ps.length?`<div class="program-grid">${ps.map(programCard).join('')}</div>`:empty('Bouw je eerste programma','Kies oefeningen uit de bibliotheek en bepaal zelf de dosering.',action('Programma maken','data-care="new-program"',true))}`;
 }
 function renderEditor(){const readonly=!!portal;
  return `<form method="dialog" id="program-editor" class="care-panel"><div class="panel-heading"><h3>${readonly?'Jouw programma':'Programma samenstellen'}</h3><div class="care-actions">${action(readonly?'Terug':'Annuleren','type="button" data-care="cancel-editor"')}${!readonly?action('Programma opslaan','type="submit"',true):''}</div></div><div class="care-form-grid"><label>Naam programma<input name="title" maxlength="100" value="${esc(draft.title)}" required ${readonly?'readonly':''}></label><label>Instructies voor de cliënt<textarea name="note" maxlength="2000" ${readonly?'readonly':''}>${esc(draft.note||'')}</textarea></label></div><fieldset class="care-days" ${readonly?'disabled':''}><legend>Trainingsdagen</legend>${[1,2,3,4,5,6,0].map(d=>`<label><input name="day" type="checkbox" value="${d}"${draft.days.includes(d)?' checked':''}>${DAYS[d]}</label>`).join('')}</fieldset>${!readonly?`<p class="care-muted small">De startwaarden zijn invulhulp. Bepaal sets, herhalingen, belasting, tempo en rust per cliënt.</p><div class="add-exercise"><label for="program-exercise">Oefening toevoegen</label><select id="program-exercise">${EX.map(e=>`<option value="${e.id}">${esc(e.n)}</option>`).join('')}</select>${action('Toevoegen','type="button" data-care="add-exercise"')}</div>`:''}<div class="program-items">${draft.items.map((i,n)=>editorItem(i,n,readonly)).join('')||'<p class="care-muted">Nog geen oefeningen toegevoegd.</p>'}</div>${!readonly?`<label class="private-field">Privénotitie voor de coach <span>Wordt niet in het cliëntportaal gedeeld.</span><textarea name="privateNote" maxlength="2000">${esc(draft.privateNote||'')}</textarea></label>`:''}<p class="form-error" id="program-error" role="alert"></p></form>`;
 }
 function editorItem(i,n,readonly){return `<article class="program-item" data-item-id="${i.id}"><div class="panel-heading"><h4><span class="item-number">${n+1}</span>${esc(ex(i.exId)?.n||i.exId)}</h4><div class="care-actions">${action('Uitleg',`type="button" data-open-exercise="${i.exId}"`)}${!readonly?action('↑',`type="button" data-reorder="${n}" data-direction="-1" aria-label="Oefening omhoog"`)+action('↓',`type="button" data-reorder="${n}" data-direction="1" aria-label="Oefening omlaag"`)+action('Verwijder',`type="button" data-remove-item="${n}"`):''}</div></div><div class="prescription-grid"><label>Sets<input data-field="sets" type="number" min="1" max="12" step="1" value="${i.sets}" required ${readonly?'readonly':''}></label><label>${i.unit==='seconds'?'Seconden':'Herhalingen'}<input data-field="reps" type="number" min="1" max="300" step="1" value="${i.reps}" required ${readonly?'readonly':''}></label><label>Eenheid<select data-field="unit" ${readonly?'disabled':''}><option value="reps"${i.unit==='reps'?' selected':''}>Herhalingen</option><option value="seconds"${i.unit==='seconds'?' selected':''}>Seconden</option></select></label><label>Belasting (kg)<input data-field="load" type="number" min="0" max="1500" step="0.25" value="${i.load}" ${readonly?'readonly':''}></label><label>Rust (sec)<input data-field="rest" type="number" min="0" max="600" step="5" value="${i.rest}" ${readonly?'readonly':''}></label><label>Tempo<input data-field="tempo" maxlength="30" placeholder="Bijv. 3-1-1-0" value="${esc(i.tempo)}" ${readonly?'readonly':''}></label></div><label>Uitvoeringsinstructie<textarea data-field="note" maxlength="500" ${readonly?'readonly':''}>${esc(i.note)}</textarea></label></article>`;}
 function collectEditor(){const f=$('program-editor');if(!f||!draft||portal)return;draft.title=f.elements.title.value.trim();draft.note=f.elements.note.value;draft.privateNote=f.elements.privateNote.value;draft.days=[...f.querySelectorAll('[name=day]:checked')].map(x=>+x.value);f.querySelectorAll('[data-item-id]').forEach(row=>{const i=draft.items.find(i=>i.id===row.dataset.itemId);row.querySelectorAll('[data-field]').forEach(el=>i[el.dataset.field]=['sets','reps','load','rest'].includes(el.dataset.field)?Number(el.value):el.value);});sessionStorage.setItem('rb-program-draft',JSON.stringify(draft));}
 function saveProgram(){collectEditor();if(!draft.items.length){$('program-error').textContent='Voeg minimaal één oefening toe.';return;}if(!C.validateProgram(draft,ids)){ $('program-error').textContent='Controleer de dosering en de invoervelden.';return;}
  draft.updatedAt=Date.now();const i=state.programs.findIndex(p=>p.id===draft.id);if(i>=0)state.programs[i]=structuredClone(draft);else state.programs.push(structuredClone(draft));if(!persist())return;draft=null;sessionStorage.removeItem('rb-program-draft');render();tell('Programma opgeslagen. Publiceer de wijziging om het cliëntportaal bij te werken.');
 }
 function startTraining(id){const p=programs().find(p=>p.id===id);if(!p?.items.length)return tell('Dit programma heeft nog geen oefeningen.');runner={id:C.uid(),program:structuredClone(p),date:C.localDate(),startedAt:Date.now()};page='dashboard';render();$('care-content').scrollIntoView({block:'start',behavior:'auto'});}
 function renderRunner(){const p=runner.program;return `<form method="dialog" id="training-log" class="care-panel runner"><div class="panel-heading"><div><span class="care-eyebrow">TRAINING UITVOEREN</span><h3>${esc(p.title)}</h3></div>${action('Later verder','type="button" data-care="pause-training"')}</div>${p.note?`<p class="client-instruction">${esc(p.note)}</p>`:''}<div class="care-form-grid"><label>Datum<input type="date" name="date" value="${runner.date}" max="${C.localDate()}" required></label><label>Ervaren inspanning (RPE 0–10)<input type="number" name="rpe" min="0" max="10" step="0.5" placeholder="0 = geen, 10 = maximaal" required></label></div>${p.items.map((i,n)=>`<section class="training-exercise"><div class="panel-heading"><div><h4>${n+1}. ${esc(ex(i.exId).n)}</h4><p>${i.sets} × ${i.reps} ${i.unit==='seconds'?'sec':'herh.'}${i.load?' · '+i.load+' kg':''}${i.tempo?' · tempo '+esc(i.tempo):''}</p></div><div class="care-actions">${action('Uitleg',`type="button" data-open-exercise="${i.exId}"`)}${action('Rust '+i.rest+'s',`type="button" data-rest="${i.rest}"`)}</div></div>${i.note?`<p>${esc(i.note)}</p>`:''}<div class="set-grid set-heading"><span>Set</span><span>${i.unit==='seconds'?'Seconden':'Herhalingen'}</span><span>kg</span><span>Gedaan</span></div>${Array.from({length:i.sets},(_,k)=>`<div class="set-grid" data-log-item="${i.id}" data-set="${k}"><span>${k+1}</span><input aria-label="${esc(ex(i.exId).n)} set ${k+1} ${i.unit==='seconds'?'seconden':'herhalingen'}" data-actual="reps" type="number" min="1" max="300" step="1" placeholder="${i.reps}"><input aria-label="${esc(ex(i.exId).n)} set ${k+1} kilogram" data-actual="load" type="number" min="0" max="1500" step="0.25" placeholder="${i.load}"><input aria-label="${esc(ex(i.exId).n)} set ${k+1} gedaan" data-actual="done" type="checkbox"></div>`).join('')}</section>`).join('')}<label>Hoe ging de training?<textarea name="note" maxlength="1000" placeholder="Bijzonderheden, aanpassingen of feedback voor de coach"></textarea></label><p class="form-error" id="training-error" role="alert"></p><div class="care-actions">${action('Training afronden','type="submit"',true)}${action('Training annuleren','type="button" data-care="cancel-training"')}</div></form><div id="rest-timer" class="rest-timer" role="status" hidden></div>`;}
 function runnerKey(){return 'rb-training-draft-'+(portal?.token||'coach')+'-'+clientRecord().id;}
 function stashRunner(){if(!runner)return;const values={};$('training-log')?.querySelectorAll('input,textarea').forEach((el,n)=>values[n]=el.type==='checkbox'?el.checked:el.value);try{localStorage.setItem(runnerKey(),JSON.stringify({runner,values}));}catch{tell('Tussentijds opslaan niet gelukt.');}}
 function restoreRunnerDraft(){const saved=read(runnerKey(),null);if(!saved||saved.runner?.id!==runner.id)return;$('training-log').querySelectorAll('input,textarea').forEach((el,n)=>{if(saved.values[n]!==undefined){if(el.type==='checkbox')el.checked=saved.values[n];else el.value=saved.values[n];}});}
 function finishTraining(){const f=$('training-log'),p=runner.program;const items=[];
  for(const i of p.items){const sets=[];for(const row of f.querySelectorAll(`[data-log-item="${i.id}"]`)){if(!row.querySelector('[data-actual=done]').checked)continue;const reps=row.querySelector('[data-actual=reps]'),load=row.querySelector('[data-actual=load]');if(!reps.value||!load.value){$('training-error').textContent='Vul herhalingen/seconden én kg in voor iedere afgevinkte set. Gebruik 0 kg voor lichaamsgewicht.';reps.focus();return;}sets.push({reps:Number(reps.value),load:Number(load.value)});}if(sets.length)items.push({exId:i.exId,unit:i.unit,sets});}
  if(!items.length){$('training-error').textContent='Vink minimaal één uitgevoerde set af.';return;}
  const s={id:runner.id,clientId:clientRecord().id,programId:p.id,title:p.title,date:f.elements.date.value,rpe:Number(f.elements.rpe.value),note:f.elements.note.value,items,createdAt:Date.now()};
  if(!C.validateSession(s,ids)||s.date>C.localDate()){ $('training-error').textContent='Controleer de datum, inspanning en uitgevoerde sets.';return;}
  if(portal){if(!portalData.sessions.some(x=>x.id===s.id))portalData.sessions.push(s);savePortalLocal();}else{if(!state.sessions.some(x=>x.id===s.id))state.sessions.push(s);if(!persist())return;}
  localStorage.removeItem(runnerKey());runner=null;stopRest();render();tell(portal?'Training opgeslagen. Resultaten worden naar je portaal verzonden.':'Training opgeslagen.');if(portal)syncPortal();
 }
 function renderProgress(){const ss=sessions(),ms=measurements();const available=[...new Set(ss.flatMap(s=>s.items.map(i=>i.exId)))];if(!available.includes(chosenExercise))chosenExercise=available[0]||'';
  const series=chosenExercise?C.exerciseSeries(ss,chosenExercise,chartMetric):[];
  const unit=chartMetric==='volume'?'kg × herhalingen':chartMetric==='reps'?(ss.flatMap(s=>s.items).filter(i=>i.exId===chosenExercise).every(i=>i.unit==='seconds')?'seconden':'herhalingen / seconden'):chartMetric==='effort'?'RPE':'kg';
  const groups=[...new Set(ms.map(m=>[m.type,m.label,m.side].join('|')))];if(!groups.includes(chartMeasure))chartMeasure=groups[0]||'';
  const selectedMs=ms.filter(m=>[m.type,m.label,m.side].join('|')===chartMeasure).sort((a,b)=>a.date.localeCompare(b.date)).slice(-12);
  return `<div class="panel-heading"><div><h3>Voortgang</h3><p class="care-muted">Vergelijk dezelfde oefening en meetmethode over tijd.</p></div>${action('Meting toevoegen','data-care="measurement"',true)}</div><section class="care-panel"><div class="chart-controls"><label>Oefening<select id="chart-exercise" aria-label="Oefening voor grafiek">${available.length?available.map(id=>`<option value="${id}"${id===chosenExercise?' selected':''}>${esc(ex(id)?.n||id)}</option>`).join(''):'<option>Nog geen trainingsgegevens</option>'}</select></label><label>Meetwaarde<select id="chart-metric" aria-label="Meetwaarde voor grafiek">${[['load','Hoogste externe belasting'],['volume','Volume (kg × herhalingen)'],['reps','Totaal herhalingen / seconden'],['effort','Ervaren inspanning (RPE)']].map(([id,label])=>`<option value="${id}"${id===chartMetric?' selected':''}>${label}</option>`).join('')}</select></label></div>${chart(series,unit,'Trainingsresultaten')}<p class="care-muted small">Externe belasting is exclusief lichaamsgewicht. Volume telt alleen sets in herhalingen met kg; houdingen in seconden tellen niet mee.</p></section><section class="care-panel"><div class="panel-heading"><h3>Metingen</h3></div>${groups.length?`<label>Meetreeks<select id="chart-measure" aria-label="Meetreeks">${groups.map(g=>`<option value="${esc(g)}"${g===chartMeasure?' selected':''}>${esc(g.replaceAll('|',' · '))}</option>`).join('')}</select></label>${chart(selectedMs,selectedMs[0]?.type==='rom'?'graden':selectedMs[0]?.type==='weight'?'kg':'score 0–10','Geregistreerde metingen')}`:'<p class="care-muted">Voeg een bewegingsuitslag, lichaamsgewicht of herstelscore toe. Gebruik dezelfde meetmethode voor een vergelijkbare reeks.</p>'}</section><section class="care-panel"><h3>Trainingslogboek</h3>${ss.length?[...ss].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<details class="session-detail"><summary>${fmt(s.date)} · ${esc(s.title||'Training')} · RPE ${s.rpe}</summary>${s.items.map(i=>`<p><b>${esc(ex(i.exId)?.n||i.exId)}</b><br>${i.sets.map((v,n)=>`Set ${n+1}: ${v.reps} ${i.unit==='seconds'?'sec':'herh.'} × ${v.load} kg`).join(' · ')}</p>`).join('')}${s.note?`<p>${esc(s.note)}</p>`:''}</details>`).join(''):'<p class="care-muted">Afgeronde trainingen verschijnen hier.</p>'}</section>`;
 }
 function chart(data,unit,title){if(!data.length)return empty('Nog geen meetpunten','Na de eerste registratie verschijnt hier je grafiek.');
  const max=Math.max(1,...data.map(x=>x.value)),x=i=>45+(data.length===1?250:i/(data.length-1)*500),y=v=>178-v/max*142;
  const points=data.map((d,i)=>`${x(i)},${y(d.value)}`).join(' ');
  return `<figure class="care-chart"><figcaption>${title} <span>${esc(unit)}</span></figcaption><svg viewBox="0 0 590 225" role="img" aria-label="${esc(title)} in ${esc(unit)}; gegevens staan ook in de tabel"><path d="M45 28V178H555" fill="none" stroke="var(--line)"/><path d="M45 107H555M45 36H555" stroke="var(--line)" stroke-dasharray="3 5"/><text x="8" y="181">0</text><text x="8" y="40">${Math.round(max)}</text><polyline points="${points}" fill="none" stroke="var(--steel)" stroke-width="3"/>${data.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d.value)}" r="5" fill="var(--steel)"><title>${fmt(d.date)}: ${d.value} ${esc(unit)}</title></circle>`).join('')}<text x="45" y="207">${fmt(data[0].date)}</text><text x="555" y="207" text-anchor="end">${fmt(data.at(-1).date)}</text></svg><details><summary>Gegevens als tabel</summary><table><thead><tr><th>Datum</th><th>${esc(unit)}</th></tr></thead><tbody>${data.map(d=>`<tr><td>${fmt(d.date)}</td><td>${d.value}</td></tr>`).join('')}</tbody></table></details></figure>`;
 }
 function renderEvaluation(){const c=clientRecord(),reviews=state.reviews.filter(r=>r.clientId===c.id).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="care-panel"><span class="care-eyebrow">SAMEN EVALUEREN</span><h3>Doel, respons en volgende stap</h3><p>${esc(c.goal||'Nog geen doel vastgelegd.')}</p><p class="care-muted">Gepland evaluatiemoment: ${fmt(c.evaluation)}</p><form method="dialog" id="evaluation-form"><div class="care-form-grid"><label>Datum<input name="date" type="date" required value="${C.localDate()}" max="${C.localDate()}"></label><label>Volgende evaluatie<input name="next" type="date" min="${C.localDate()}"></label></div><label>Bevindingen en afgesproken aanpassingen<textarea name="note" maxlength="2000" rows="5" required placeholder="Wat ging goed? Wat veranderde? Welke aanpassing spreken jullie af?"></textarea></label>${action('Evaluatie opslaan','type="submit"',true)}</form></section><section class="care-panel"><h3>Eerdere evaluaties</h3>${reviews.length?reviews.map(r=>`<article class="review-entry"><b>${fmt(r.date)}</b><p>${esc(r.note)}</p>${r.next?`<small>Volgende evaluatie: ${fmt(r.next)}</small>`:''}</article>`).join(''):'<p class="care-muted">Hier verschijnen je opgeslagen evaluaties.</p>'}</section>`;}
 function clientDialog(edit=false){const c=edit?clientRecord():null;showDialog(edit?'Cliëntprofiel':'Nieuwe cliënt',`<form method="dialog" id="client-form"><input type="hidden" name="id" value="${c?.id||''}"><label>Naam of cliëntalias<input name="name" maxlength="80" value="${esc(c?.name||'')}" required autocomplete="off"></label><label>Doel<textarea name="goal" maxlength="500" placeholder="Concreet doel en belangrijke aandachtspunten">${esc(c?.goal||'')}</textarea></label><div class="care-form-grid"><label>Startdatum<input name="start" type="date" value="${c?.start||C.localDate()}" required></label><label>Evaluatiedatum<input name="evaluation" type="date" value="${c?.evaluation||''}"></label></div><p class="care-muted small">Gebruik op gedeelde apparaten bij voorkeur een herkenbare alias.</p>${action('Profiel opslaan','type="submit"',true)}</form>`);}
 function measurementDialog(){showDialog('Meting vastleggen',`<form method="dialog" id="measurement-form"><div class="care-form-grid"><label>Datum<input name="date" type="date" value="${C.localDate()}" max="${C.localDate()}" required></label><label>Meettype<select name="type"><option value="rom">Bewegingsuitslag (graden)</option><option value="weight">Lichaamsgewicht (kg)</option><option value="recovery">Ervaren herstel (0–10)</option></select></label></div><label>Naam meetreeks / meetmethode<input name="label" maxlength="100" required placeholder="Bijv. kniebuiging actief met goniometer"></label><div class="care-form-grid"><label>Zijde<select name="side"><option value="">Niet van toepassing</option><option>Links</option><option>Rechts</option><option>Beide</option></select></label><label>Meetwaarde<input name="value" type="number" min="0" max="360" step="0.1" required></label></div><p class="care-muted small">Herstelscore: 0 = helemaal niet hersteld, 10 = volledig hersteld. Dit is een eigen registratie, geen klinische testuitslag.</p>${action('Meting opslaan','type="submit"',true)}</form>`);}
 function dataDialog(){showDialog('Gegevens & cliëntportaal',`<p>Cliëntprofielen en programma’s staan op dit toestel. Maak een reservekopie om ze zelf te bewaren of naar een ander coachapparaat over te zetten.</p><div class="care-actions">${action('Versleutelde reservekopie','data-care="backup"',true)}${action('Reservekopie importeren','data-care="import"')}</div><hr><h3>Cliëntportaal</h3><p>Iedere cliënt krijgt een afzonderlijke portaalcode. Alleen de eigen programma’s en resultaten worden gedeeld.</p><div class="care-actions">${clientRecord()?action('Geselecteerd portaal beheren','data-care="portal"'):''}${action('Cliëntportaal openen','data-care="join-portal"')}</div>`);}
 async function portalRequest(method,credentials,body,owner=false){const r=await fetch('/api/portal',{method,headers:{Authorization:'Bearer '+credentials.token,...(body?{'Content-Type':'application/json'}:{}),...(owner?{'X-Portal-Owner':credentials.owner}:{})},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store',signal:AbortSignal.timeout(25000)});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Portaal niet bereikbaar');return data;}
 function portalDialog(){const c=clientRecord(),p=state.portals[c.id];showDialog('Portaal van '+esc(c.name),`<p>Deel alleen deze privécode met deze cliënt. Privénotities van de coach worden niet meegestuurd. Een code geeft toegang tot het eigen programma en de eigen resultaten.</p>${p?`<label>Portaalcode<textarea id="portal-code" readonly></textarea></label><div class="care-actions">${action('Code kopiëren','data-care="copy-portal"')}${action('Programma bijwerken','data-care="publish-portal"',true)}${action('Resultaten ophalen','data-care="pull-results"')}${action('Toegang intrekken','data-care="revoke-portal"')}</div><p class="care-muted small">Laatste publicatie: ${p.published?new Date(p.published).toLocaleString('nl-NL'):'Nog niet gepubliceerd'}</p>`:action('Privéportaal publiceren','data-care="publish-portal"',true)}<p id="portal-message" role="status"></p>`);if(p)modal.querySelector('#portal-code').value='rbp1_'+p.token+'_'+p.key;}
 async function publishPortal(){if(portalBusy)return;portalBusy=true;const id=selected,c=state.clients.find(c=>c.id===id);const credentials=state.portals[id]||{token:K.random(),key:K.random(),owner:K.random()};const status=modal.querySelector('#portal-message');if(status)status.textContent='Programma versleutelen en publiceren…';
  try{const snapshot=C.clientSnapshot(state,id);const assignedIds=new Set(snapshot.programs.flatMap(p=>p.items.map(i=>i.exId)));snapshot.customVideos=Object.fromEntries(Object.entries(read('rb-demo-links',{})).filter(([id,url])=>assignedIds.has(id)&&videoLink(url)));if(!snapshot.programs.some(p=>p.items.length))throw new Error('Maak eerst een programma met oefeningen voor deze cliënt.');await portalRequest('POST',credentials,{action:'publish',plan:await K.encrypt(snapshot,credentials.key)},true);credentials.published=Date.now();state.portals[id]=credentials;persist();portalDialog();tell('Privéportaal gepubliceerd. Deel de code met de cliënt.');}catch(e){formError(e.message);}finally{portalBusy=false;}}
 function joinPortalDialog(){showDialog('Cliëntportaal openen',`<form method="dialog" id="join-portal-form"><p>Gebruik de privécode die je van je coach hebt gekregen.</p><label>Portaalcode<input name="code" type="password" autocomplete="off" required placeholder="rbp1_…"></label>${action('Portaal openen','type="submit"',true)}</form>`);}
 async function joinPortal(code){if(portalBusy)return;portalBusy=true;try{const credentials=K.parse(code);const data=await portalRequest('GET',credentials);const snapshot=await K.decrypt(data.plan,credentials.key);if(!C.validateSnapshot(snapshot,ids))throw new Error('Ongeldig programma in dit portaal.');portal=credentials;portalData={...snapshot,sessions:[],measurements:[]};const cached=read('rb-portal-data-'+portal.token,null);if(cached&&cached.client?.id===snapshot.client.id){portalData.sessions=cached.sessions||[];portalData.measurements=cached.measurements||[];}await mergePortalLogs(data.logs);localStorage.setItem('rb-active-portal',JSON.stringify(credentials));savePortalLocal();page='dashboard';draft=null;runner=null;modal.close();switchTab(5);render();}catch(e){formError(e.message||'De code kon niet worden geopend.');}finally{portalBusy=false;}}
 function savePortalLocal(){try{localStorage.setItem('rb-portal-data-'+portal.token,JSON.stringify(portalData));}catch{tell('Lokale opslag van het portaal is vol.');}}
 async function mergePortalLogs(logs){for(const d of logs){const result=await K.decrypt(d.payload,portal.key);const tmp={sessions:portalData.sessions,measurements:portalData.measurements};C.mergeResults(tmp,result,portalData.client.id,ids);}}
 async function syncPortal(){if(!portal||portalBusy)return;portalBusy=true;const credentials=portal;try{const payload=await K.encrypt({version:1,sessions:portalData.sessions,measurements:portalData.measurements},credentials.key);let device=read('rb-portal-device','');if(!/^[a-f0-9]{32}$/.test(device)){device=K.random(16);localStorage.setItem('rb-portal-device',JSON.stringify(device));}await portalRequest('POST',credentials,{action:'log',device,payload});const data=await portalRequest('GET',credentials);if(portal!==credentials)return;const snapshot=await K.decrypt(data.plan,credentials.key);if(!C.validateSnapshot(snapshot,ids))throw new Error('Ongeldig programma');portalData={...portalData,...snapshot};await mergePortalLogs(data.logs);savePortalLocal();const el=$('portal-status');if(el)el.textContent='Bijgewerkt om '+new Date().toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'});if(!runner&&cur===5)render();}catch(e){tell(e.message||'Offline: je resultaten blijven bewaard en worden later verzonden.');}finally{portalBusy=false;}}
 async function pullResults(){if(portalBusy)return;portalBusy=true;try{const p=state.portals[selected];if(!p)throw new Error('Er is nog geen portaal.');const data=await portalRequest('GET',p);const before=state.sessions.length+state.measurements.length;for(const log of data.logs)C.mergeResults(state,await K.decrypt(log.payload,p.key),selected,ids);persist();modal.close();render();tell((state.sessions.length+state.measurements.length-before)+' nieuwe registraties opgehaald.');}catch(e){formError(e.message);}finally{portalBusy=false;}}
 async function revokePortal(){if(portalBusy)return;portalBusy=true;try{const p=state.portals[selected];await portalRequest('POST',p,{action:'revoke'},true);delete state.portals[selected];persist();portalDialog();tell('Portaaltoegang ingetrokken. Een nieuw portaal krijgt een nieuwe code.');}catch(e){formError(e.message);}finally{portalBusy=false;}}
 async function backup(){showDialog('Versleutelde reservekopie',`<form method="dialog" id="backup-form"><p>Je reservekopie bevat programma’s, registraties en eventuele portaalcodes. Kies een wachtwoord van minimaal 12 tekens en bewaar het zelf.</p><label>Wachtwoord<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label>Herhaal wachtwoord<input name="repeat" type="password" minlength="12" required autocomplete="new-password"></label>${action('Reservekopie downloaden','type="submit"',true)}</form>`);}
 async function passwordKey(password,salt){const raw=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const b=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new Uint8Array(salt),iterations:250000,hash:'SHA-256'},raw,256);return Array.from(new Uint8Array(b),n=>n.toString(16).padStart(2,'0')).join('');}
 function download(data,name){const blob=new Blob([JSON.stringify(data)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
 function importDialog(){showDialog('Reservekopie importeren',`<form method="dialog" id="import-form"><p>De reservekopie wordt gecontroleerd en toegevoegd. Bestaande registraties met hetzelfde ID blijven behouden.</p><label>Reservekopie<input name="file" type="file" accept=".json,.rehaboom" required></label><label>Wachtwoord<input name="password" type="password" minlength="12" required autocomplete="current-password"></label>${action('Importeren','type="submit"',true)}</form>`);}
 function templates(){const list=state.programs.filter(p=>p.items.length);showDialog('Programma als sjabloon gebruiken',list.length?`<p>Maak een zelfstandige kopie voor ${esc(clientRecord().name)}. Pas de dosering aan vóór gebruik.</p>${list.map(p=>`<button class="template-option" data-template="${p.id}"><b>${esc(p.title)}</b><span>${p.items.length} oefeningen</span></button>`).join('')}`:'<p>Maak eerst een programma. Daarna kun je dat als sjabloon voor een andere cliënt gebruiken.</p>');}
 function addFromLibrary(id){if(!state.clients.length){showDialog('Eerst een cliënt toevoegen','<p>Maak een cliëntprofiel aan om een persoonlijk programma samen te stellen.</p>'+action('Cliënt toevoegen','data-care="new-client"',true));return;}showDialog('Toevoegen aan programma',`<form method="dialog" id="library-add-form"><input type="hidden" name="exercise" value="${id}"><p>${esc(ex(id).n)}</p><label>Cliënt<select name="clientId">${state.clients.map(c=>`<option value="${c.id}"${c.id===selected?' selected':''}>${esc(c.name)}</option>`).join('')}</select></label><p class="care-muted small">De oefening wordt toegevoegd aan het laatst bewerkte programma, of aan een nieuw programma als er nog geen is. Controleer de dosering vóór opslaan.</p>${action('Naar programmabouwer','type="submit"',true)}</form>`);}
 function stopRest(){clearInterval(restInterval);restUntil=0;const el=$('rest-timer');if(el)el.hidden=true;}
 function rest(seconds){stopRest();if(!seconds)return;restUntil=Date.now()+seconds*1000;const tick=()=>{const el=$('rest-timer');if(!el)return stopRest();const left=Math.max(0,Math.ceil((restUntil-Date.now())/1000));el.hidden=false;el.textContent=left?'Rust · '+Math.floor(left/60)+':'+String(left%60).padStart(2,'0'):'Rust afgerond';if(!left)clearInterval(restInterval);};tick();restInterval=setInterval(tick,250);}
 document.addEventListener('submit',async event=>{
  const f=event.target;if(!['program-editor','training-log','client-form','measurement-form','evaluation-form','join-portal-form','backup-form','import-form','library-add-form','review-form','demo-link-form'].includes(f.getAttribute('id')))return;event.preventDefault();
  try{
   if(f.getAttribute('id')==='program-editor')saveProgram();
   if(f.getAttribute('id')==='training-log')finishTraining();
   if(f.getAttribute('id')==='client-form'){
    const c={id:f.elements.id.value||C.uid(),name:f.elements.name.value.trim(),goal:f.elements.goal.value.trim(),start:f.elements.start.value,evaluation:f.elements.evaluation.value};
    if(!c.name||!C.validateState({...C.empty(),clients:[c]},ids))throw new Error('Controleer naam en datums.');
    const index=state.clients.findIndex(x=>x.id===c.id);if(index>=0)state.clients[index]=c;else state.clients.push(c);selected=c.id;persist();modal.close();page='dashboard';draft=null;switchTab(5);render();
   }
   if(f.getAttribute('id')==='measurement-form'){
    const m={id:C.uid(),clientId:clientRecord().id,date:f.elements.date.value,type:f.elements.type.value,label:f.elements.label.value.trim(),side:f.elements.side.value,value:Number(f.elements.value.value)};
    if(!C.validateState({...C.empty(),measurements:[m]},ids)||m.date>C.localDate())throw new Error('Controleer de meetwaarde en datum.');
    if(portal){portalData.measurements.push(m);savePortalLocal();syncPortal();}else{state.measurements.push(m);persist();}modal.close();page='progress';render();tell('Meting opgeslagen.');
   }
   if(f.getAttribute('id')==='evaluation-form'){
    const r={id:C.uid(),clientId:selected,date:f.elements.date.value,next:f.elements.next.value,note:f.elements.note.value.trim()};
    if(!r.note||!C.validateState({...C.empty(),reviews:[r]},ids)||r.date>C.localDate())throw new Error('Controleer de evaluatiegegevens.');
    state.reviews.push(r);const c=clientRecord();c.evaluation=r.next||'';persist();render();tell('Evaluatie opgeslagen.');
   }
   if(f.getAttribute('id')==='join-portal-form')await joinPortal(f.elements.code.value);
   if(f.getAttribute('id')==='backup-form'){
    const password=f.elements.password.value;if(password.length<12||password!==f.elements.repeat.value)throw new Error('Gebruik tweemaal hetzelfde wachtwoord van minimaal 12 tekens.');
    const salt=crypto.getRandomValues(new Uint8Array(16)),secret=await passwordKey(password,salt),payload=await K.encrypt(state,secret);
    download({format:'rehaboom-backup',version:1,salt:[...salt],payload},'rehaboom-reservekopie-'+C.localDate()+'.json');modal.close();tell('Versleutelde reservekopie aangemaakt.');
   }
   if(f.getAttribute('id')==='import-form'){
    const file=f.elements.file.files[0];if(!file||file.size>8000000)throw new Error('Kies een reservekopie van maximaal 8 MB.');
    const data=JSON.parse(await file.text());if(data.format!=='rehaboom-backup'||data.version!==1||!Array.isArray(data.salt)||data.salt.length!==16||!data.salt.every(x=>Number.isInteger(x)&&x>=0&&x<256))throw new Error('Dit is geen geldige reservekopie.');
    let incoming;try{incoming=await K.decrypt(data.payload,await passwordKey(f.elements.password.value,data.salt));}catch{throw new Error('Het wachtwoord klopt niet of het bestand is beschadigd.');}
    if(!C.validateState(incoming,ids))throw new Error('De gegevens zijn niet geldig voor deze appversie.');
    for(const type of ['clients','programs','sessions','measurements','reviews'])for(const entity of incoming[type])if(!state[type].some(x=>x.id===entity.id))state[type].push(entity);
    for(const [id,p] of Object.entries(incoming.portals||{}))if(state.clients.some(c=>c.id===id)&&/^[a-f0-9]{64}$/.test(p.token||'')&&/^[a-f0-9]{64}$/.test(p.key||'')&&/^[a-f0-9]{64}$/.test(p.owner||'')&&!state.portals[id])state.portals[id]=p;
    selected=selected||state.clients[0]?.id||'';persist();modal.close();render();tell('Reservekopie toegevoegd. Bestaande items zijn behouden.');
   }
   if(f.getAttribute('id')==='library-add-form'){
    collectEditor();selected=f.elements.clientId.value;const latest=state.programs.filter(p=>p.clientId===selected&&!p.archived).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0))[0];draft=latest?structuredClone(latest):newProgram();draft.items.push(newItem(f.elements.exercise.value));page='programs';modal.close();switchTab(5);render();
   }
   if(f.getAttribute('id')==='review-form'){
    const record={name:f.elements.reviewer.value.trim(),date:f.elements.date.value,note:f.elements.note.value.trim()};if(!record.name||!C.validDate(record.date)||record.date>C.localDate())throw new Error('Vul je naam en een geldige reviewdatum in.');
    const reviews=read('rb-content-reviews',{});reviews[f.elements.topic.value]=record;localStorage.setItem('rb-content-reviews',JSON.stringify(reviews));modal.close();renderO();renderG();renderT();tell('Eigen review vastgelegd.');
   }
   if(f.getAttribute('id')==='demo-link-form'){
    const raw=f.elements.url.value.trim();const links=read('rb-demo-links',{});if(raw&&!videoLink(raw))throw new Error('Gebruik een YouTube-link of een HTTPS-link naar een MP4-video.');
    if(raw)links[f.elements.exercise.value]=raw;else delete links[f.elements.exercise.value];localStorage.setItem('rb-demo-links',JSON.stringify(links));modal.close();renderO();tell('Videolink opgeslagen. Publiceer het cliëntportaal opnieuw om deze te delen.');
   }
  }catch(e){const local=f.querySelector('.form-error');if(local)local.textContent=e.message;else if(modal.open)formError(e.message);else tell(e.message);}
 });
 document.addEventListener('click',async event=>{
  const b=event.target.closest('button');if(!b)return;
  try{
   if(b.hasAttribute('data-care-close'))modal.close();
   if(b.dataset.care==='share-app')shareAppDialog();
   if(b.dataset.care==='copy-app-link')await copyAppLink();
   if(b.dataset.carePage){if(runner)stashRunner();runner=null;draft=null;page=b.dataset.carePage;render();}
   if(b.dataset.addToProgram)addFromLibrary(b.dataset.addToProgram);
   if(b.dataset.editProgram){const p=programs().find(p=>p.id===b.dataset.editProgram);if(p){draft=structuredClone(p);page='programs';render();}}
   if(b.dataset.startProgram)startTraining(b.dataset.startProgram);
   if(b.dataset.openExercise){stashRunner();const index=EX.findIndex(x=>x.id===b.dataset.openExercise);if(index>=0){ei=index;$('ex-search').value='';savedExercisesOnly=false;switchTab(2);renderO();showReturnButton();}}
   if(b.dataset.removeItem!==undefined){collectEditor();draft.items.splice(+b.dataset.removeItem,1);render();}
   if(b.dataset.reorder!==undefined){collectEditor();const i=+b.dataset.reorder,j=i+(+b.dataset.direction);if(j>=0&&j<draft.items.length)[draft.items[i],draft.items[j]]=[draft.items[j],draft.items[i]];render();}
   if(b.dataset.template){const p=state.programs.find(p=>p.id===b.dataset.template);if(p){draft={...structuredClone(p),id:C.uid(),clientId:selected,title:p.title+' · kopie',privateNote:'',items:p.items.map(i=>({...i,id:C.uid()}))};modal.close();page='programs';render();}}
   if(b.dataset.rest!==undefined)rest(+b.dataset.rest);
   if(b.dataset.demoPlay)playDemo(b);
   if(b.dataset.demoLink){showDialog('Eigen oefenvideo',`<form method="dialog" id="demo-link-form"><input name="exercise" type="hidden" value="${b.dataset.demoLink}"><p>Voeg een passende demonstratie toe. Controleer zelf de uitvoering en het gebruiksrecht. YouTube wordt pas geladen wanneer iemand de video start.</p><label>Videolink<input name="url" type="url" maxlength="1000" placeholder="https://…" value="${esc(read('rb-demo-links',{})[b.dataset.demoLink]||'')}"></label>${action('Videolink opslaan','type="submit"',true)}</form>`);}
   if(b.dataset.reviewTopic)reviewDialog(b.dataset.reviewTopic);
   if(b.hasAttribute('data-motion-play'))toggleMotion();
   if(b.hasAttribute('data-motion-reset')){stopMotion();motionValue=0;paintMotion();}
   const a=b.dataset.care;if(!a)return;
   if(a==='new-client')clientDialog();if(a==='edit-client'&&!portal)clientDialog(true);
   if(a==='data')dataDialog();if(a==='backup')backup();if(a==='import')importDialog();if(a==='templates')templates();
   if(a==='new-program'&&!portal){draft=newProgram();page='programs';switchTab(5);render();}
   if(a==='add-exercise'){collectEditor();if(draft.items.length>=40)return tell('Een programma kan maximaal 40 oefeningen bevatten.');draft.items.push(newItem($('program-exercise').value));render();}
   if(a==='cancel-editor'){draft=null;sessionStorage.removeItem('rb-program-draft');render();}
   if(a==='measurement')measurementDialog();
   if(a==='pause-training'){stashRunner();runner=null;stopRest();render();tell('Training tussentijds opgeslagen.');}
   if(a==='resume-training'){const saved=read(runnerKey(),null);if(saved?.runner&&saved.runner.program?.clientId===clientRecord().id){runner=saved.runner;render();}else tell('Geen bewaarde training gevonden.');}
   if(a==='cancel-training'){showDialog('Training annuleren',`<p>De nog niet afgeronde sets worden niet als resultaat opgeslagen.</p>${action('Verder trainen','data-care="keep-training"',true)}${action('Annuleren bevestigen','data-care="confirm-cancel-training"')}`);}
   if(a==='keep-training')modal.close();if(a==='confirm-cancel-training'){localStorage.removeItem(runnerKey());runner=null;stopRest();modal.close();render();}
   if(a==='portal'&&!portal){if(modal.open)modal.close();portalDialog();}
   if(a==='publish-portal'&&!portal)publishPortal();if(a==='copy-portal'){try{await navigator.clipboard.writeText(modal.querySelector('#portal-code').value);tell('Privécode gekopieerd.');}catch{modal.querySelector('#portal-code').select();}}
   if(a==='pull-results'&&!portal)pullResults();if(a==='revoke-portal'&&!portal){showDialog('Portaaltoegang intrekken',`<p>De huidige code van ${esc(clientRecord().name)} werkt daarna niet meer. Opgeslagen gegevens op het toestel van de cliënt kunnen op afstand niet worden gewist.</p>${action('Terug','data-care="portal"')}${action('Toegang intrekken bevestigen','data-care="confirm-revoke"')}`);}
   if(a==='confirm-revoke')revokePortal();if(a==='join-portal')joinPortalDialog();if(a==='refresh-portal')syncPortal();
   if(a==='leave-portal'){if(runner)stashRunner();portal=null;portalData=null;runner=null;draft=null;page='dashboard';localStorage.removeItem('rb-active-portal');stopRest();render();}
   if(a==='return-care'){switchTab(5);render();$('return-care')?.remove();}
  }catch(e){if(modal.open)formError(e.message);else tell(e.message);}
 });
 document.addEventListener('change',event=>{
  const el=event.target;
  if(el.id==='care-client'){if(runner)stashRunner();selected=el.value;runner=null;draft=null;page='dashboard';render();}
  if(el.id==='chart-exercise'){chosenExercise=el.value;render();}if(el.id==='chart-metric'){chartMetric=el.value;render();}if(el.id==='chart-measure'){chartMeasure=el.value;render();}
  if(el.closest('#program-editor')&&!portal)collectEditor();if(el.closest('#training-log'))stashRunner();
  if(el.name==='type'&&el.closest('#measurement-form')){const f=el.form;f.elements.value.max=el.value==='rom'?360:el.value==='weight'?500:10;}
 });
 document.addEventListener('input',event=>{if(event.target.closest('#program-editor')&&!portal)collectEditor();if(event.target.closest('#training-log'))stashRunner();if(event.target.id==='motion-position'){motionValue=Number(event.target.value);stopMotion();paintMotion();}});
 function showReturnButton(){let b=$('return-care');if(!b){b=document.createElement('button');b.id='return-care';b.className='care-return';b.dataset.care='return-care';b.textContent=runner?'Verder met training':'Terug naar programma';document.body.append(b);}}

 // Demonstrations are separate from anatomy rotations, with explicit attribution.
 function videoLink(raw){try{const u=new URL(raw);if(u.protocol!=='https:')return null;const host=u.hostname.toLowerCase();let id;if(host==='youtu.be')id=u.pathname.slice(1);else if(['youtube.com','www.youtube.com','m.youtube.com'].includes(host))id=u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed)\/([\w-]+)/)?.[1];if(id&&/^[\w-]{11}$/.test(id))return {type:'youtube',src:'https://www.youtube-nocookie.com/embed/'+id};if(/\.mp4$/i.test(u.pathname)&&!u.username&&!u.password)return {type:'video',src:u.href};}catch{}return null;}
 function demonstration(e){const custom=read('rb-demo-links',{})[e.id]||(portalData?.customVideos||{})[e.id],data=custom?videoLink(custom):null,v=VIDEO_CATALOG[e.id];
  return `<section class="exercise-demo" aria-label="Uitvoering ${esc(e.n)}"><div class="panel-heading"><div><span class="care-eyebrow">UITVOERING</span><h4>Zo ziet de oefening eruit</h4></div>${!portal?action('Eigen videolink',`type="button" data-demo-link="${e.id}"`):''}</div>${data||v?`${!data&&v?.variant?`<p class="demo-variant">${esc(v.variant)}</p>`:''}<div class="demo-stage" id="demo-${e.id}"><div class="demo-placeholder"><span class="demo-play-icon" aria-hidden="true">▶</span><p>${data?'Eigen demonstratie':esc(v.title)}</p>${action('Bekijk demonstratie',`type="button" data-demo-play="${e.id}"`,true)}</div></div><p class="demo-credit">${data?'Eigen videolink · inhoud en rechten te controleren door de coach.':`${esc(v.author)} via wger · <a href="${v.licenseUrl}" target="_blank" rel="noopener noreferrer">${v.license}</a> · <a href="${v.source}" target="_blank" rel="noopener noreferrer">Bron</a><br>${esc(v.adaptation)}`}</p>`:`<div class="demo-no-video"><b>Uitvoeringskaart</b><p>Voor deze variant is nog geen bronvideo toegevoegd. De coach kan hier een eigen demonstratie koppelen.</p></div>`}<div class="execution-steps"><div><span>01</span><b>Oefening & positie</b><p>${esc(e.d)}</p></div><div><span>02</span><b>Uitvoering</b><p>${esc(e.cue)}</p></div><div><span>03</span><b>Dosering</b><p>Volg het persoonlijke programma voor belasting, tempo, herhalingen en rust.</p></div></div></section>`;
 }
 function playDemo(b){const id=b.dataset.demoPlay,custom=read('rb-demo-links',{})[id]||(portalData?.customVideos||{})[id],link=custom?videoLink(custom):null,v=VIDEO_CATALOG[id],stage=$('demo-'+id);if(!stage)return;
  if(link?.type==='youtube'){const iframe=document.createElement('iframe');iframe.src=link.src;iframe.title='Oefendemonstratie '+ex(id).n;iframe.allow='fullscreen; picture-in-picture';iframe.referrerPolicy='strict-origin-when-cross-origin';iframe.setAttribute('allowfullscreen','');stage.replaceChildren(iframe);return;}
  const src=link?.src||v?.src;if(!src)return;const video=document.createElement('video');video.src=src;video.controls=true;video.playsInline=true;video.preload='metadata';video.setAttribute('aria-label','Demonstratie '+ex(id).n);video.addEventListener('error',()=>{stage.replaceChildren();const p=document.createElement('p');p.className='video-error';p.textContent='Deze demonstratie kon niet worden geladen. De uitvoeringskaart blijft beschikbaar.';stage.append(p);});stage.replaceChildren(video);video.load();
 }
 function reviewPanel(topic){const r=read('rb-content-reviews',{})[topic];return `<details class="quality-panel"><summary>Bronnen & inhoudelijke controle <span class="quality-status">${r?'Eigen review vastgelegd':'Vakinhoudelijke review open'}</span></summary><p>Bronnen en licenties staan bij de betreffende beelden en oorspronkelijke uitleg. Een aanwezige bronvermelding is geen volledige klinische validatie.</p>${r?`<p><b>Eigen review:</b> ${esc(r.name)} · ${fmt(r.date)}</p>${r.note?`<p>${esc(r.note)}</p>`:''}`:'<p>Voor dit onderdeel is nog geen inhoudelijke reviewer geregistreerd.</p>'}${!portal?action('Eigen review vastleggen',`type="button" data-review-topic="${esc(topic)}"`):''}</details>`;}
 function reviewDialog(topic){const r=read('rb-content-reviews',{})[topic];showDialog('Eigen inhoudelijke review',`<form method="dialog" id="review-form"><input type="hidden" name="topic" value="${esc(topic)}"><p>Leg vast dat jij dit onderdeel hebt nagekeken. Dit wordt als eigen review getoond.</p><label>Naam reviewer<input name="reviewer" maxlength="100" value="${esc(r?.name||'')}" required></label><label>Reviewdatum<input name="date" type="date" max="${C.localDate()}" value="${r?.date||C.localDate()}" required></label><label>Reikwijdte en opmerkingen<textarea name="note" maxlength="1000">${esc(r?.note||'')}</textarea></label>${action('Review vastleggen','type="submit"',true)}</form>`);}

 // Regional motion model with a local fallback and source anatomy beside it.
 let motionValue=0,motionRunning=false,motionFrame=0,motionStart=0,motionLast=null,motionScope=null,motionBones=true,motionDirection=true;
 function motionPanel(){const j=J[ji],p=j.planes[pi];const scope=j.id+':'+pi;
  if(motionScope!==scope){motionScope=scope;motionValue=0;motionLast=null;}
  const chosen=p.moves.find(m=>m.id===motionLast)||p.moves[0];motionLast=chosen.id;
  const pilot=Boolean(window.rbShoulderMotion?.moves[chosen.id]);
  const hasModel=Boolean(window.rbMotion3d?.definitions[chosen.id]);
  const model=pilot ? 'Geïllustreerde bewegingsdemo' : 'Schematisch leermodel';
  return `<section class="motion-panel care-panel" aria-label="Beweging verkennen"><div class="panel-heading"><div><span class="care-eyebrow">BEWEGING VERKENNEN</span><h3>${esc(j.short)} · ${esc(p.plane)}</h3></div></div><label>Beweging<select id="motion-move">${p.moves.map(m=>`<option value="${m.id}"${m.id===chosen.id?' selected':''}>${esc(m.t)}</option>`).join('')}</select></label><div class="motion-layout${(pilot||hasModel)?' motion-layout-pilot':''}"><div class="motion-diagram"><svg id="motion-svg" viewBox="${pilot?'0 0 420 350':'0 0 360 280'}" role="img" aria-label="${model}"><defs><pattern id="motion-grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="currentColor" opacity=".07"/></pattern></defs><rect width="360" height="280" fill="url(#motion-grid)"/><g id="motion-bone-shapes"></g><g id="motion-muscle-shapes"></g><circle cx="180" cy="140" r="12" fill="var(--surface)" stroke="var(--coral)" stroke-width="3"/><circle cx="180" cy="140" r="3" fill="var(--coral)"/></svg><span class="motion-label" id="motion-caption">${model}</span></div><figure class="motion-reference"><img src="anatomy/interactive/${j.id}.webp" alt="Statische anatomische referentie van ${esc(j.short.toLowerCase())}" loading="lazy"><figcaption>Anatomische referentie · blijft stilstaand</figcaption></figure></div><div class="motion-controls">${action('Afspelen','type="button" data-motion-play aria-pressed="false"')}${action('Beginpositie','type="button" data-motion-reset')}<label><input type="checkbox" id="motion-bones"${motionBones?' checked':''}><span id="motion-mark-label">Botsegmenten</span></label><label><input type="checkbox" id="motion-muscles"${motionDirection?' checked':''}>Bewegingsrichting</label></div><label>Positie in de demonstratie<input id="motion-position" type="range" min="0" max="100" value="${motionValue}" aria-label="Positie in bewegingsdemonstratie"></label><p id="motion-description" class="motion-description"></p><div id="motion-muscles-list"></div><p id="motion-note" class="care-muted small">${pilot?'De stippellijn markeert de beginpositie. De schuif geeft de voortgang van de demo aan. Voor botdetails en aanhechtingen kun je de anatomische referentie en atlas openen.':'De animatie toont de bewegingsrichting met vereenvoudigde segmenten. Geen anatomisch 3D-model, gemeten gewrichtshoek of exacte spieraanhechting. Raadpleeg de atlas voor de structuren.'}</p></section>`;
 }
 function stopMotion(){motionRunning=false;cancelAnimationFrame(motionFrame);const b=document.querySelector('[data-motion-play]');if(b){b.textContent='Afspelen';b.setAttribute('aria-pressed','false');}}
 function paintMotion(){const svg=$('motion-svg');if(!svg)return;const j=J[ji],p=j.planes[pi],m=p.moves.find(m=>m.id===motionLast)||p.moves[0];
  const progress=motionValue/100,pilot=window.rbShoulderMotion?.moves[m.id];
  svg.motionFallback ??= svg.innerHTML;
  const rendered=window.rbMotion3d?.draw(svg,m.id,progress,motionBones,motionDirection,paintMotion);
  if(rendered||pilot)svg.setAttribute('viewBox','0 0 420 350');
  if(rendered){
   svg.setAttribute('aria-label',m.t+' · '+(pilot?pilot[3]:m.d));
   $('motion-caption').textContent='3D-bewegingsmodel';
   $('motion-mark-label').textContent='Gewricht markeren';
   $('motion-note').innerHTML='Het open bolletje markeert het begin van de bewegingsbaan. De schuif toont de voortgang. De illustratie is bedoeld om de richting te leren. <a href="https://www.makehumancommunity.org/about/license.html" target="_blank" rel="noopener noreferrer">Mensmodel: MakeHuman (CC0)</a>.';
  }else if(pilot){
   svg.setAttribute('aria-label',m.t+' · '+pilot[3]);
   svg.innerHTML=window.rbShoulderMotion.render(m.id,progress,motionBones,motionDirection);
  }else{
   svg.setAttribute('viewBox','0 0 360 280');
   if(!$('motion-bone-shapes'))svg.innerHTML=svg.motionFallback;
   paintSchematic(m,j,p,progress);
  }
  $('motion-position').value=motionValue;$('motion-description').textContent=pilot?pilot[3]:m.d;
  if($('motion-muscles-list').dataset.move!==m.id){$('motion-muscles-list').dataset.move=m.id;$('motion-muscles-list').innerHTML=`<p class="care-eyebrow">PRIMAIRE SPIEREN VOLGENS DE BEWEGINGSKAART</p><div class="chips">${m.ag.map(([n])=>`<button class="chip r-ag" data-m="${esc(n)}">${esc(n)}</button>`).join('')}</div>`;}
 }
 function paintSchematic(m,j,p,progress){const bone=$('motion-bone-shapes'),muscle=$('motion-muscle-shapes');const negative=/ext|retro|add|depr|drot|retr|endo|inv|pron/.test(m.id)?-1:1;const angle=negative*progress*75;
  const end=[180+105*Math.sin(angle*Math.PI/180),140+105*Math.cos(angle*Math.PI/180)];
  if(p.axis==='L')bone.innerHTML=`<ellipse cx="180" cy="140" rx="94" ry="42" fill="none" stroke="var(--muted)" stroke-width="8"/><g transform="rotate(${angle} 180 140)"><path d="M180 140L270 140" stroke="var(--ink)" stroke-width="15" stroke-linecap="round"/><circle cx="270" cy="140" r="10" fill="var(--surface)" stroke="var(--ink)" stroke-width="4"/></g>`;
  else if(j.id==='sg')bone.innerHTML=`<path d="M180 45V235" stroke="var(--muted)" stroke-width="18" stroke-linecap="round"/><path d="M120 75L75 150L130 200Z" fill="var(--steel-bg)" stroke="var(--ink)" stroke-width="6" transform="translate(${p.axis==='T'?0:progress*25} ${p.axis==='T'?-negative*progress*50:0}) rotate(${p.axis==='T'?0:angle/2} 120 140)"/>`;
  else bone.innerHTML=`<path d="M180 140V42" stroke="var(--muted)" stroke-width="20" stroke-linecap="round"/><path d="M180 140L${end[0]} ${end[1]}" stroke="var(--ink)" stroke-width="20" stroke-linecap="round"/><path d="M180 140L${end[0]} ${end[1]}" stroke="var(--surface)" stroke-width="8" stroke-linecap="round"/>${j.id==='nk'?`<circle cx="${end[0]}" cy="${end[1]}" r="24" fill="var(--steel-bg)" stroke="var(--ink)" stroke-width="3"/>`:''}`;
  muscle.innerHTML=`<path d="M135 140Q125 ${160+progress*25} ${end[0]-18} ${end[1]-10}" fill="none" stroke="var(--coral)" stroke-width="5" stroke-linecap="round" stroke-dasharray="7 7"/><text x="20" y="26" fill="var(--steel)" font-size="12">${esc(m.t)}</text>`;
  bone.style.display=motionBones?'':'none';muscle.style.display=motionDirection?'':'none';
 }
 function toggleMotion(){if(motionRunning)return stopMotion();motionRunning=true;motionStart=performance.now()-Math.acos(1-2*motionValue/100)*1800/Math.PI;const b=document.querySelector('[data-motion-play]');b.textContent='Pauzeren';b.setAttribute('aria-pressed','true');const tick=now=>{if(!motionRunning||cur!==0||!$('motion-svg')?.getClientRects().length)return stopMotion();const next=Math.round((1-Math.cos((now-motionStart)/1800*Math.PI))*50);if(next!==motionValue){motionValue=next;paintMotion();}motionFrame=requestAnimationFrame(tick);};motionFrame=requestAnimationFrame(tick);}
 document.addEventListener('click',e=>{if(e.target.closest('[data-joint-section="beweging"]'))paintMotion();});
 document.addEventListener('change',e=>{if(e.target.id==='motion-move'){stopMotion();motionLast=e.target.value;motionValue=0;paintMotion();}if(e.target.id==='motion-bones'){motionBones=e.target.checked;paintMotion();}if(e.target.id==='motion-muscles'){motionDirection=e.target.checked;paintMotion();}});
 const previousO=renderO,previousG=renderG,previousSheet=openSheet,previousT=renderT,previousSwitch=switchTab;
 renderO=function(){previousO();const card=$('exc'),e=EX[ei];if(card){card.querySelector('.cue.big')?.insertAdjacentHTML('beforebegin',demonstration(e));if(!portal)card.querySelector('h3')?.parentElement.insertAdjacentHTML('beforeend',action('In programma zetten',`type="button" data-add-to-program="${e.id}"`));card.insertAdjacentHTML('beforeend',reviewPanel('exercise:'+e.id));}};
 renderG=function(){stopMotion();document.querySelectorAll('#joint-motion .motion-panel').forEach(el=>el.remove());previousG();$('axis').insertAdjacentHTML('afterend',motionPanel());paintMotion();$('joint-anatomy').insertAdjacentHTML('beforeend',reviewPanel('joint:'+J[ji].id));};
 openSheet=function(name){previousSheet(name);document.querySelector('.sheet')?.insertAdjacentHTML('beforeend',reviewPanel('muscle:'+name));};
 renderT=function(){previousT();$('tests').insertAdjacentHTML('afterend',reviewPanel('tests:'+TJ[tj]));const duplicates=$('view-t').querySelectorAll('.quality-panel');duplicates.forEach((x,i)=>{if(i<duplicates.length-1)x.remove();});};
 switchTab=function(i){if(cur===5&&runner)stashRunner();previousSwitch(i);if(i===5){$('return-care')?.remove();render();}if(i!==0)stopMotion();else paintMotion();};
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMotion();if(runner)stashRunner();}else if(portal)syncPortal();});addEventListener('online',()=>{if(portal)syncPortal();});
 addEventListener('pagehide',()=>{if(runner)stashRunner();});
 const savedPortal=read('rb-active-portal',null);if(savedPortal?.token&&savedPortal?.key){const cached=read('rb-portal-data-'+savedPortal.token,null);if(cached&&C.validateSnapshot(cached,ids)){portal=savedPortal;portalData=cached;}}
 renderO();renderG();renderT();render();if(cur===5&&portal)syncPortal();
 // Tests can inspect the public state without exposing portal secrets.
 window.rbCareSummary=()=>({clients:state.clients.length,programs:state.programs.length,sessions:state.sessions.length,measurements:state.measurements.length,portal:!!portal});
})();
